import assert from 'node:assert/strict';
import { test } from 'node:test';

import { slugify } from '../src/slugify.js';

// Regression: repeated separators and surrounding punctuation must collapse to a single
// hyphen, and must not produce empty segments at either end.
test('slugify collapses repeated separators', () => {
  assert.equal(slugify('  Hello   World!!  '), 'hello-world');
});

test('slugify strips leading and trailing punctuation', () => {
  assert.equal(slugify('--Hello World--'), 'hello-world');
});
